{"content": "def trim_history(messages: list[dict], budget: int) -> list[dict]:
    """Returns the longest contiguous suffix of messages whose summed cost fits budget.
    Each message is a dict with an integer 'cost' key.
    Validates that budget and all costs are nonnegative.
    """
    if not isinstance(budget, int) or budget < 0:
        raise ValueError(f"budget must be a nonnegative integer, not {budget!r}")

    for i, m in enumerate(messages):
        if not isinstance(m, dict) or "cost" not in m or not isinstance(m["cost"], int) or m["cost"] < 0:
            raise ValueError(f"message at index {i} must have a nonnegative integer 'cost'")

    current_sum = 0
    suffix_start = len(messages)

    # Iterate backwards to find the longest contiguous suffix
    for i in range(len(messages) - 1, -1, -1):
        cost = messages[i]["cost"]
        if current_sum + cost <= budget:
            current_sum += cost
            suffix_start = i
        else:
            break

    return [m.copy() for m in messages[suffix_start:]]
