def merge_tool_results(calls, results):
    seen_ids = set()
    for call in calls:
        cid = call.get('id')
        if cid is None:
            continue
        if cid in seen_ids:
            raise ValueError(f"Duplicate call id: {cid}")
        seen_ids.add(cid)

    result_map = {}
    for res in results:
        rid = res.get('id')
        if rid in seen_ids:
            result_map[rid] = res.get('content', '')

    output = []
    for call in calls:
        cid = call.get('id')
        if cid is None:
            continue
        if cid in result_map:
            output.append({'id': cid, 'status': 'done', 'content': result_map[cid]})
        else:
            output.append({'id': cid, 'status': 'pending'})

    return output

