def summarize_usage(events):
    """Summarize total input and output tokens across all requests.

    Events have request_id and optional nonnegative integer input/output token counts, 
    which are cumulative snapshots for that request. For each request, keep the 
    maximum seen input and output counts independently, then sum across requests. 
    Missing counts mean 0. Reject any negative count with ValueError. 
    Return {'input':total, 'output':total}; do not mutate events.
    """
    request_max_input = {}
    request_max_output = {}

    for event in events:
        req_id = event.get("request_id")
        if req_id is None:
            continue

        # Validate and update input
        in_count = event.get("input")
        if in_count is not None:
            if not isinstance(in_count, int) or in_count < 0:
                raise ValueError(f"Invalid input: {in_count}")
            request_max_input[req_id] = max(request_max_input.get(req_id, 0), in_count)

        # Validate and update output
        out_count = event.get("output")
        if out_count is not None:
            if not isinstance(out_count, int) or out_count < 0:
                raise ValueError(f"Invalid output: {out_count}")
            request_max_output[req_id] = max(request_max_output.get(req_id, 0), out_count)

    total_input = sum(request_max_input.values())
    total_output = sum(request_max_output.values())

    return {"input": total_input, "output": total_output}

